// Node consumer using AsyncIterator + adapter:
const resp = await client.streamMessages({stream: true});
for await (const msg of StreamBridge.fromWebStream(resp.body, {retryPolicy: defaultPolicy})) {
  handle(msg);
}
// Browser fetch consumer using SDK helper to get ReadableStream:
const {stream} = await client.streamChat({prompt});
const webStream = StreamBridge.toWebStream(stream, {highWaterMark: 8});
const reader = webStream.getReader();
while (true) {
  const {value, done} = await reader.read();
  if (done) break;
  renderChunk(value);
}
// Bidi example (client-side):
const input = new ReadableStream({
  start(controller) { /* push messages from mic or UI */ }
});
const serverStream = await client.openRealtime({input: StreamBridge.fromWebStream(input)});
for await (const out of serverStream) {
  playAudio(out.audioChunk);
}
